    "formatName": "mov,mp4 (AVFoundation adapter)"
  },
  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 3.32,
        "text": "搬平台三万本全平台五万份目标达成"
      },
      {
        "start": 3.32,
        "end": 7.16,
        "text": "长等律博房律互动律军令先同类形作者百分之九十八以上"
      },
      {
        "start": 7.16,
        "end": 8.6,
        "text": "而且连续多日当日长份"
      },
      {
        "start": 8.6,
        "end": 11.2,
        "text": "超过一千多个我今天就要做一期视频"
      },
      {
        "start": 11.2,
        "end": 14.32,
        "text": "包括这段时间运营我AS媒体频道的全部新发"
      },
      {
        "start": 14.32,
        "end": 16.08,
        "text": "毫无保留的分享给大家"
      },
      {
        "start": 16.08,
        "end": 18.44,
        "text": "首先第一个就是大家最关注我的变现的问题"
      },
      {
        "start": 18.44,
        "end": 19.36,
        "text": "我在近七天"
      },
      {
        "start": 19.36,
        "end": 21.64,
        "text": "博房量变现这一块是一千两百多块钱"
      },
      {
        "start": 21.64,
        "end": 23.8,
        "text": "我的财互自由船是八百多块钱"
      },
      {
        "start": 23.8,
        "end": 25.2,
        "text": "所以加起来是两千多"
      },
      {
        "start": 25.2,
        "end": 26.28,
        "text": "我其实还是挺满的"
      },
      {
        "start": 26.28,
        "end": 27.2,
        "text": "因为在这个过程中"
      },
      {
        "start": 27.2,
        "end": 29.28,
        "text": "我是已经拒绝掉了三到四个商单"
      },
      {
        "start": 29.28,
        "end": 31.52,
        "text": "我为什么因为我现在接的粉丝量还不是特别多"
      },
      {
        "start": 31.52,
        "end": 32.72,
        "text": "这些商单和我也不是特别匹"
      },
      {
        "start": 32.72,
        "end": 34.64,
        "text": "说白来他们大家也不会特别高"
      },
      {
        "start": 34.64,
        "end": 35.72,
        "text": "我觉得问题不是特别大"
      },
      {
        "start": 35.72,
        "end": 38,
        "text": "毕竟AI塞到作为现在全平台商业的价值"
      },
      {
        "start": 38,
        "end": 39.56,
        "text": "所以高的一个塞到"
      },
      {
        "start": 39.56,
        "end": 42.08,
        "text": "只要你有流量未来的变现能力应该是不仇的"
      },
      {
        "start": 42.08,
        "end": 43.12,
        "text": "而且其实对于我来说"
      },
      {
        "start": 43.12,
        "end": 44.64,
        "text": "并没有这么急于去变现"
      },
      {
        "start": 44.64,
        "end": 45.88,
        "text": "是不是一句装逼的话"
      },
      {
        "start": 45.88,
        "end": 47.52,
        "text": "大家可以去看一下创为老总"
      },
      {
        "start": 47.52,
        "end": 50.04,
        "text": "黄红生前陣子发的一条视频他讲的"
      },
      {
        "start": 50.04,
        "end": 51.84,
        "text": "是很多人不能成功的原因"
      },
      {
        "start": 51.84,
        "end": 53.72,
        "text": "因为是因为向行拥有任何"
      },
      {
        "start": 53.72,
        "end": 54.36,
        "text": "这说的是什么"
      },
      {
        "start": 54.36,
        "end": 55.92,
        "text": "就是在你做一件事情的时候"
      },
      {
        "start": 55.92,
        "end": 58.12,
        "text": "太过于向抓住救命倒草"
      },
      {
        "start": 58.12,
        "end": 60.56,
        "text": "一样的抓住他太想一定要成功"
      },
      {
        "start": 60.56,
        "end": 61.6,
        "text": "比如说如果我做自媒体"
      },
      {
        "start": 61.6,
        "end": 63,
        "text": "我一定要通过这个去变现能多钱"
      },
      {
        "start": 63,
        "end": 63.92,
        "text": "给自己定下这个目标"
      },
      {
        "start": 63.92,
        "end": 65.2,
        "text": "我所有的动作都会变现"
      },
      {
        "start": 65.2,
        "end": 66.24,
        "text": "我现在给自己定的目标"
      },
      {
        "start": 66.24,
        "end": 66.84,
        "text": "是年底之前"
      },
      {
        "start": 66.84,
        "end": 68.8,
        "text": "你尽量把全平台的粉丝做到50万"
      },
      {
        "start": 68.8,
        "end": 70,
        "text": "那我的心态是什么呢"
      },
      {
        "start": 70,
        "end": 71.8,
        "text": "我的心态不是说这事一定要成"
      },
      {
        "start": 71.8,
        "end": 73.76,
        "text": "而是我把它当成一个游戏"
      },
      {
        "start": 73.76,
        "end": 75.36,
        "text": "一步一步的去打通关"
      },
      {
        "start": 75.36,
        "end": 75.72,
        "text": "大家知道"
      },
      {
        "start": 75.72,
        "end": 77.36,
        "text": "实际上你在运营自媒体知道的时候"
      },
      {
        "start": 77.36,
        "end": 78.96000000000001,
        "text": "你会看到非常多的问题"
      },
      {
        "start": 78.96000000000001,
        "end": 80.12,
        "text": "比如说像选皮的问题"
      },
      {
        "start": 80.12,
        "end": 81.2,
        "text": "比如说像脏粉的问题"
      },
      {
        "start": 81.2,
        "end": 83.4,
        "text": "比如说像切商单变现的问题"
      },
      {
        "start": 83.4,
        "end": 88.4,
        "text": "实际上这个多是打怪升级中的一道一道看"
      },
      {
        "start": 88.4,
        "end": 89.16,
        "text": "那在这个过程中"
      },
      {
        "start": 89.16,
        "end": 89.96000000000001,
        "text": "什么时候我的第一个原因"
      },
      {
        "start": 89.96000000000001,
        "end": 92.75999999999999,
        "text": "就是把每期视频的内容给它做好"
      },
      {
        "start": 92.75999999999999,
        "end": 94.52000000000001,
        "text": "让我的粉丝们有看到有货的感"
      },
      {
        "start": 94.52000000000001,
        "end": 95.52000000000001,
        "text": "这个才是最重要的"
      },
      {
        "start": 95.52000000000001,
        "end": 96.68,
        "text": "而不是变现"
      },
      {
        "start": 96.68,
        "end": 98.47999999999999,
        "text": "我相信你只要把事情做好"
      },
      {
        "start": 98.47999999999999,
        "end": 100.08,
        "text": "变现非常简单"
      },
      {
        "start": 100.08,
        "end": 100.8,
        "text": "第二个问题就是"
      },
      {
        "start": 100.8,
        "end": 102.2,
        "text": "大家在我后台护生最高"
      },
      {
        "start": 102.2,
        "end": 103.75999999999999,
        "text": "最关注的就是我的这个工作流"
      },
      {
        "start": 103.75999999999999,
        "end": 105.12,
        "text": "实际上大家是对于我这视频"
      },
      {
        "start": 105.12,
        "end": 106.03999999999999,
        "text": "怎么做包装"
      },
      {
        "start": 106.03999999999999,
        "end": 106.8,
        "text": "这些动物效果"
      },
      {
        "start": 106.8,
        "end": 108.24000000000001,
        "text": "为什么能做这么高级"
      },
      {
        "start": 108.24000000000001,
        "end": 109.12,
        "text": "是非常好奇的"
      },
      {
        "start": 109.12,
        "end": 110.16,
        "text": "那我实际上之前是做了"
      },
      {
        "start": 110.16,
        "end": 111.8,
        "text": "以及非常详细的工作流教学"
      },
      {
        "start": 111.8,
        "end": 112.96000000000001,
        "text": "我今天就稍微再来"
      },
      {
        "start": 112.96000000000001,
        "end": 114.03999999999999,
        "text": "讲一下这个事情"
      },
      {
        "start": 114.03999999999999,
        "end": 115.84,
        "text": "除了前期的选题"
      },
      {
        "start": 115.84,
        "end": 119.03999999999999,
        "text": "我是用Hermes在AI号的上进行一个信员扫名"
      },
      {
        "start": 119.03999999999999,
        "end": 121.08,
        "text": "以及用Codex来关注我评论"
      },
      {
        "start": 121.08,
        "end": 122.24,
        "text": "去大家关心的一些问题"
      },
      {
        "start": 122.24,
        "end": 123.08,
        "text": "确定选题"
      },
      {
        "start": 123.08,
        "end": 123.96,
        "text": "这是第一步之外"
      },
      {
        "start": 123.96,
        "end": 125.36,
        "text": "其实最重要的就是一个视频包装"
      },
      {
        "start": 125.36,
        "end": 126.2,
        "text": "我现在主要就是用"
      },
      {
        "start": 126.2,
        "end": 128.8,
        "text": "Remotion这个开源的软性来做这个事"
      },
      {
        "start": 128.8,
        "end": 129.28,
        "text": "当然了"
      },
      {
        "start": 129.28,
        "end": 130,
        "text": "现在也出了一个叫"
      },
      {
        "start": 130,
        "end": 131.52,
        "text": "HyperFrames的简直软件"
      },
      {
        "start": 131.52,
        "end": 133.84,
        "text": "它可以根据的口播生成视频"
      },
      {
        "start": 133.84,
        "end": 134.4,
        "text": "但我看了一下"
      },
      {
        "start": 134.4,
        "end": 136.04,
        "text": "实际上那个是并不能达到我的要求"
      },
      {
        "start": 136.04,
        "end": 137.12,
        "text": "那么为什么能做这么好"
      },
      {
        "start": 137.12,
        "end": 139.32,
        "text": "除了你去安装一个Remotion的核心依赖"
      },
      {
        "start": 139.32,
        "end": 141.28,
        "text": "以外实际上我的整个过程"
      },
      {
        "start": 141.28,
        "end": 142.56,
        "text": "是不断的进行蝶带"
      },
      {
        "start": 142.56,
        "end": 144.07999999999998,
        "text": "所以我经过了几个月时间蝶带"
      },
      {
        "start": 144.07999999999998,
        "end": 145.07999999999998,
        "text": "一开始做出来的效果"
      },
      {
        "start": 145.07999999999998,
        "end": 146.52,
        "text": "其实是非常差距的"
      },
      {
        "start": 146.52,
        "end": 147.36,
        "text": "在这个过程中"
      },
      {
        "start": 147.36,
        "end": 148.16,
        "text": "我一个是给它使用了"
      },
      {
        "start": 148.16,
        "end": 150.52,
        "text": "最好的奥斯典C的一个模型"
      },
      {
        "start": 150.52,
        "end": 152.07999999999998,
        "text": "一个是我们每一次"
      },
      {
        "start": 152.07999999999998,
        "end": 154.52,
        "text": "都不是让它期限地去给我完成一个项目"
      },
      {
        "start": 154.52,
        "end": 155.76,
        "text": "而是我跟它一起完成"
      },
      {
        "start": 155.76,
        "end": 157.28,
        "text": "我在它做动效的过程中"
      },
      {
        "start": 157.28,
        "end": 158.92000000000002,
        "text": "不断地对它进行调试"
      },
      {
        "start": 158.92000000000002,
        "end": 160.84,
        "text": "每一次做完一个视频以后"
      },
      {
        "start": 160.84,
        "end": 162.36,
        "text": "对整个项目进行回顾"
      },
      {
        "start": 162.36,
        "end": 164.12,
        "text": "让它在肆格欧库里面进行更新"
      },
      {
        "start": 164.12,
        "end": 166.88,
        "text": "所以我现在有非常多的Remotion的肆格"
      },
      {
        "start": 166.88,
        "end": 168.16,
        "text": "包括长篇的动效专配"
      },
      {
        "start": 168.16,
        "end": 169.76,
        "text": "包括风格偏好"
      },
      {
        "start": 169.76,
        "end": 172.28,
        "text": "包括错题级 包括音效设计"
      },
      {
        "start": 172.28,
        "end": 174.32,
        "text": "有一个跌掉了非常多版本的一个"
      },
      {
        "start": 174.32,
        "end": 175.24,
        "text": "肆格欧库在这里"
      },
      {
        "start": 175.24,
        "end": 177.2,
        "text": "那我每一次在进行制作的时候"
      },
      {
        "start": 177.2,
        "end": 178.48,
        "text": "我都可以动用这个肆格欧库"
      },
      {
        "start": 178.48,
        "end": 179.68,
        "text": "那就可以保证"
      },
      {
        "start": 179.68,
        "end": 181.28,
        "text": "它能一次做的比一次好"
      },
      {
        "start": 181.28,
        "end": 182.24,
        "text": "那现在为止"
      },
      {
        "start": 182.24,
        "end": 184.04,
        "text": "这个效果应该是我算是比较满意的"
      },
      {
        "start": 184.04,
        "end": 185.88,
        "text": "所以说如果你也想用Remotion"
      },
      {
        "start": 185.88,
        "end": 186.92,
        "text": "欢迎你来资讯我"
      },
      {
        "start": 186.92,
        "end": 189.36,
        "text": "最重要的一步是一场就是你每次做完以后"
      },
      {
        "start": 189.36,
        "end": 191.2,
        "text": "都让它复盘总结"
      },
      {
        "start": 191.2,
        "end": 191.64,
        "text": "一直更新"
      },
      {
        "start": 191.64,
        "end": 192.92,
        "text": "它就能越做越好"
      },
      {
        "start": 192.92,
        "end": 193.92,
        "text": "在Remotion的价值下"
      },
      {
        "start": 193.92,
        "end": 195.92,
        "text": "确实也大幅缩短了我的一个简直压力"
      },
      {
        "start": 195.92,
        "end": 197.36,
        "text": "那现在就可以导致我的更新频率"
      },
      {
        "start": 197.36,
        "end": 199.64,
        "text": "可以做到日耿这也是我一直想要的"
      },
      {
        "start": 199.64,
        "end": 200.52,
        "text": "说实话"
      },
      {
        "start": 200.52,
        "end": 201.96,
        "text": "作品质量的优先度是"
      },
      {
        "start": 201.96,
        "end": 204.8,
        "text": "源源小于你更新频率的优先度的"
      },
      {
        "start": 204.8,
        "end": 206.56,
        "text": "大家知道你如果一周发一条视频"
      },
      {
        "start": 206.56,
        "end": 209.4,
        "text": "你这条视频报款的可能是远低于你"
      },
      {
        "start": 209.4,
        "end": 210.72,
        "text": "一周发五条视频"
      },
      {
        "start": 210.72,
        "end": 212.36,
        "text": "甚至一天发75条视频"
      },
      {
        "start": 212.36,
        "end": 214.16,
        "text": "这就是川昌龙老师教大家的"
      },
      {
        "start": 214.16,
        "end": 215.32,
        "text": "但是这边就要说到一个"
      },
      {
        "start": 215.32,
        "end": 216.44,
        "text": "就在我的工作流"
      },
      {
        "start": 216.44,
        "end": 218.04,
        "text": "你们有一些是AI可以参与的"
      },
      {
        "start": 218.04,
        "end": 221.12,
        "text": "但是有一些工程是绝对不允许AI参与的"
      },
      {
        "start": 221.12,
        "end": 223.16,
        "text": "我是非常反犯这个AI的"
      },
      {
        "start": 223.16,
        "end": 224.56,
        "text": "AI可以去看影视剧问方天宏"
      },
      {
        "start": 224.56,
        "end": 225.64,
        "text": "就是听不老师说了"
      },
      {
        "start": 225.64,
        "end": 227.44,
        "text": "他们在一期视频里面有一个片段"
      },
      {
        "start": 227.44,
        "end": 228.56,
        "text": "是用了AI生成的"
      },
      {
        "start": 228.56,
        "end": 230.52,
        "text": "但是大家的骂神就特别高"
      },
      {
        "start": 230.52,
        "end": 231,
        "text": "这是为什么"
      },
      {
        "start": 231,
        "end": 232.44,
        "text": "现在大家本能的会认为"
      },
      {
        "start": 232.44,
        "end": 234.76,
        "text": "AI做出来的东西就是联价"
      },
      {
        "start": 234.76,
        "end": 236.56,
        "text": "所以在我的工作流程里面哪些环节"
      },
      {
        "start": 236.56,
        "end": 238,
        "text": "绝对是不允许AI参与的"
      },
      {
        "start": 238,
        "end": 238.72,
        "text": "第一"
      },
      {
        "start": 238.72,
        "end": 240.16,
        "text": "坚持真人出境"
      },
      {
        "start": 240.16,
        "end": 241.68,
        "text": "绝对不能采用什么AI人"
      },
      {
        "start": 241.68,
        "end": 244.12,
        "text": "或者AI口播去替代我做这些事情"
      },
      {
        "start": 244.12,
        "end": 244.72,
        "text": "第二"
      },
      {
        "start": 244.72,
        "end": 247.44,
        "text": "绝对不能造念AI的告字"
      },
      {
        "start": 247.44,
        "end": 249.68,
        "text": "我在信息搜集的时候是有用到AI工具"
      },
      {
        "start": 249.68,
        "end": 251.92,
        "text": "但是我一定是要用我自己的能力"
      },
      {
        "start": 251.92,
        "end": 253.36,
        "text": "去对它进行一个理解"
      },
      {
        "start": 253.36,
        "end": 254.2,
        "text": "而且我在理解完以后"
      },
      {
        "start": 254.2,
        "end": 256.96,
        "text": "还要把这个东西回一个完全不懂AI的朋友进行交流"
      },
      {
        "start": 256.96,
